def add(a, b):
    return a + b

def multiply(a, b):
    return a * b

operations = {
    "+": add,
    "*": multiply,
}

def calculate(a, op, b):
    return operations[op](a, b)

print(calculate(3, "+", 4))   # 7
print(calculate(3, "*", 4))   # 12

words = ["banana", "kiwi", "fig"]
print(sorted(words, key=len))   # ['fig', 'kiwi', 'banana'] -- sorted by length, shortest first

def memoize(fn):
    cache = {}
    def wrapper(*args):
        if args not in cache:
            cache[args] = fn(*args)
        return cache[args]
    return wrapper

def slow_square(n):
    print(f"computing square of {n}...")
    return n * n

slow_square = memoize(slow_square)

print(slow_square(4))   # 'computing square of 4...' then 16
print(slow_square(4))   # just 16 -- cache hit, no recomputation
print(slow_square(5))   # 'computing square of 5...' then 25
